import React, { useEffect, useState } from "react";

function Packets() {
  const [packets, setPackets] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/packets")
      .then((res) => res.json())
      .then((data) => {
        console.log("Packets:", data);
        setPackets(data);
      })
      .catch((err) =>
        console.error("Packets error:", err)
      );
  }, []);

  return (
    <div>
      <h1>Packets</h1>

      {packets.length === 0 ? (
        <p>No packets found.</p>
      ) : (
        packets.map((item, index) => (
          <div
            key={index}
            style={styles.card}
          >
            <p>Source: {item.source_ip}</p>
            <p>Destination: {item.destination_ip}</p>
            <p>Protocol: {item.protocol}</p>
          </div>
        ))
      )}
    </div>
  );
}

const styles = {
  card: {
    background: "#1e293b",
    padding: "20px",
    marginBottom: "15px",
    borderRadius: "10px",
    color: "white"
  }
};

export default Packets;
